 * All API calls exported from this file will be added
 * to the reducer, saga and props of index.js
 */
import createAPICall from 'utils/helperFunctions/createAPICall';
import axios from 'axios';
import createReducer from 'utils/helperFunctions/createReducer';
import { TITLE_A_TO_Z } from './constants';
import uuid from 'uuid/v4';

const container = 'homePage';

export const getProductsCall = createAPICall({
  name: 'getProducts',
  container,
  apiCallParams: () => [
    [axios, axios.get],
    `https://j-parre.myshopify.com/products.json`,
  ],
});

export const basketState = createReducer({
  name: 'basket',
  container,
  initialState: {
    items: [],
  },
  actions: {
    add: (state, payload) => ({
      ...state,
      /** Here, we are adding an _id property to guarantee uniqueness  */
      items: [...(state.items || []), { ...payload, _id: uuid() }],
    }),
    removeById: (state, id) => ({
      ...state,
      items: state.items.filter((item: { _id: string }) => item._id !== id),
    }),
    changeById: (state, { id, newItem }) => ({
      ...state,
      items: state.items.map((item: { _id: string }) => {
        if (item._id === id) return newItem;
        return item;
      }),
    }),
    clearAll: state => ({ ...state, items: [] }),
  },
});

export const orderState = createReducer({
  name: 'order',
  container,
  initialState: {
    type: TITLE_A_TO_Z,
  },
  actions: {
    change: (state, payload) => ({ ...state, type: payload }),
  },
});

import ApiCallPropTypes from './ApiCallPropTypes';

export default interface NestedApiCallPropTypes {
  /** The state of the API call */
  state: ApiCallPropTypes;
  /** Submits the API call */
  submit: (params?: any) => void;
  /** Resets the API call state to its default */
  reset: () => void;
}

import reduceToObject from 'utils/helperFunctions/reduceToObject';

function ApiCallArray(apiCalls: any) {
  this.array = Object.keys(apiCalls).map(key => apiCalls[key]);
}

ApiCallArray.prototype.mapStateToProps = function mapStateToProps() {
  return this.array
    .map((apiCall: any) => ({ [apiCall.name]: apiCall.mapStateToProps() }))
    .reduce(reduceToObject, {});
};

ApiCallArray.prototype.mapNestedStateToProps = function mapNestedStateToProps() {
  return this.array
    .map((apiCall: any) => ({
      [apiCall.name]: apiCall.mapNestedStateToProps(),
    }))
    .reduce(reduceToObject, {});
};

ApiCallArray.prototype.mapDispatchToProps = function mapDispatchToProps(
  dispatch: Function,
) {
  return this.array
    .map((apiCall: any) => ({
      ...apiCall.mapDispatchToProps(dispatch),
    }))
    .reduce(reduceToObject, {});
};

ApiCallArray.prototype.mapNestedDispatchToProps = function mapNestedDispatchToProps(
  dispatch: Function,
) {
  return this.array
    .map((apiCall: any) => ({
      ...apiCall.mapNestedDispatchToProps(dispatch),
    }))
    .reduce(reduceToObject, {});
};

ApiCallArray.prototype.mergeNestedProps = function mergeNestedProps() {
  return (stateProps: any, dispatchProps: any, otherProps: any) => {
    const mergedProps = Object.keys(stateProps)
      .map(key => {
        if (!Object.keys(dispatchProps).includes(key)) {
          return { [key]: stateProps[key] };
        }
        return { [key]: { ...stateProps[key], ...dispatchProps[key] } };
      })
      .reduce(reduceToObject, {});
    return {
      ...dispatchProps,
      ...stateProps,
      ...mergedProps,
      ...otherProps,
    };
  };
};

ApiCallArray.prototype.mapReducers = function mapReducers() {
  return this.array
    .map((apiCall: any) => ({ [apiCall.name]: apiCall.reducer }))
    .reduce(reduceToObject, {});
};

ApiCallArray.prototype.mapSaga = function mapSaga() {
  return this.array
    .map(({ saga }: { saga: any }) => [saga])
    .reduce((a: any, b: any) => [...a, ...b], []);
};

export default ApiCallArray;

export default interface ApiCallPropTypes {
  isLoading: boolean;
  hasError: boolean;
  errorMessage: string;
  hasSucceeded: boolean;
  data: any;
  prevPayload?: any;
}

// No need to build the DLL in production
if (process.env.NODE_ENV === 'production') {
  process.exit(0);
}

require('shelljs/global');

const path = require('path');
const fs = require('fs');
const exists = fs.existsSync;
const writeFile = fs.writeFileSync;

const defaults = require('lodash/defaultsDeep');
const pkg = require(path.join(process.cwd(), 'package.json'));
const config = require('../config');
const dllConfig = defaults(pkg.dllPlugin, config.dllPlugin.defaults);
const outputPath = path.join(process.cwd(), dllConfig.path);
const dllManifestPath = path.join(outputPath, 'package.json');

/**
 * I use node_modules/react-boilerplate-dlls by default just because
 * it isn't going to be version controlled and babel wont try to parse it.
 */
mkdir('-p', outputPath);

echo('Building the Webpack DLL...');

/**
 * Create a manifest so npm install doesn't warn us
 */
if (!exists(dllManifestPath)) {
  writeFile(
    dllManifestPath,
    JSON.stringify(
      defaults({
        name: 'react-boilerplate-dlls',
        private: true,
        author: pkg.author,
        repository: pkg.repository,
        version: pkg.version,
      }),
      null,
      2,
    ),
    'utf8',
  );
}

// the BUILDING_DLL env var is set to avoid confusing the development environment
exec(
  'cross-env BUILDING_DLL=true webpack --display-chunks --color --config internals/webpack/webpack.dll.babel.js --hide-modules',
);

/**
 * Test route reducer
 */

import { LOCATION_CHANGE } from 'react-router-redux';
import { routeReducer } from '../reducers';

describe('route reducer', () => {
  it('should return the initial state', () => {
    const initialState = { foo: 'bar' };
    expect(routeReducer(initialState, {})).toEqual(initialState);
  });

  it('should handle the location_change action correctly', () => {
    const state = { location: 'somewhere' };
    const payload = 'elsewhere';
    const action = { type: LOCATION_CHANGE, payload };

    const expectedState = { location: payload };
    const resultState = routeReducer(state, action);
    expect(resultState).toEqual(expectedState);
  });
});

import { formatTranslationMessages } from '../i18n';

jest.mock('../translations/en.json', () => ({
  message1: 'default message',
  message2: 'default message 2',
}));

const esTranslationMessages = {
  message1: 'mensaje predeterminado',
  message2: '',
};

describe('formatTranslationMessages', () => {
  it('should build only defaults when DEFAULT_LOCALE', () => {
    const result = formatTranslationMessages('en', { a: 'a' });

    expect(result).toEqual({ a: 'a' });
  });

  it('should combine default locale and current locale when not DEFAULT_LOCALE', () => {
    const result = formatTranslationMessages('', esTranslationMessages);

    expect(result).toEqual({
      message1: 'mensaje predeterminado',
      message2: 'default message 2',
    });
  });
});

// needed for regenerator-runtime
// (ES7 generator support is required by redux-saga)
import 'babel-polyfill';

/**
 * Test store addons
 */

import { browserHistory } from 'react-router-dom';
import configureStore from '../configureStore';

describe('configureStore', () => {
  let store;

  beforeAll(() => {
    store = configureStore({}, browserHistory);
  });

  describe('injectedReducers', () => {
    it('should contain an object for reducers', () => {
      expect(typeof store.injectedReducers).toBe('object');
    });
  });

  describe('injectedSagas', () => {
    it('should contain an object for sagas', () => {
      expect(typeof store.injectedSagas).toBe('object');
    });
  });

  describe('runSaga', () => {
    it('should contain a hook for `sagaMiddleware.run`', () => {
      expect(typeof store.runSaga).toBe('function');
    });
  });
});

describe('configureStore params', () => {
  it('should call window.__REDUX_DEVTOOLS_EXTENSION_COMPOSE__', () => {
    /* eslint-disable no-underscore-dangle */
    const compose = jest.fn();
    window.__REDUX_DEVTOOLS_EXTENSION_COMPOSE__ = () => compose;
    configureStore(undefined, browserHistory);
    expect(compose).toHaveBeenCalled();
    /* eslint-enable */
  });
});

import languageProviderReducer from '../reducer';
import { CHANGE_LOCALE } from '../constants';

describe('languageProviderReducer', () => {
  it('returns the initial state', () => {
    expect(languageProviderReducer(undefined, {})).toEqual({
      locale: 'en',
    });
  });

  it('changes the locale', () => {
    expect(
      languageProviderReducer(undefined, {
        type: CHANGE_LOCALE,
        locale: 'de',
      }),
    ).toEqual({
      locale: 'de',
    });
  });
});

import { selectLanguage } from '../selectors';

describe('selectLanguage', () => {
  it('should select the global state', () => {
    const globalState = {};
    const mockedState = {
      language: globalState,
    };
    expect(selectLanguage(mockedState)).toEqual(globalState);
  });
});

import React from 'react';
import { shallow, mount } from 'enzyme';
import { FormattedMessage, defineMessages } from 'react-intl';
import { Provider } from 'react-redux';
import { browserHistory } from 'react-router-dom';

import ConnectedLanguageProvider, { LanguageProvider } from '../index';
import configureStore from '../../../configureStore';

import { translationMessages } from '../../../i18n';

const messages = defineMessages({
  someMessage: {
    id: 'some.id',
    defaultMessage: 'This is some default message',
    en: 'This is some en message',
  },
});

describe('<LanguageProvider />', () => {
  it('should render its children', () => {
    const children = (<h1>Test</h1>);
    const renderedComponent = shallow(
      <LanguageProvider messages={messages} locale="en">
        {children}
      </LanguageProvider>
    );
    expect(renderedComponent.contains(children)).toBe(true);
  });
});

describe('<ConnectedLanguageProvider />', () => {
  let store;

  beforeAll(() => {
    store = configureStore({}, browserHistory);
  });

  it('should render the default language messages', () => {
    const renderedComponent = mount(
      <Provider store={store}>
        <ConnectedLanguageProvider messages={translationMessages}>
          <FormattedMessage {...messages.someMessage} />
        </ConnectedLanguageProvider>
      </Provider>
    );
    expect(renderedComponent.contains(<FormattedMessage {...messages.someMessage} />)).toBe(true);
  });
});
